read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
old=read(BASE/'coordinate-yolo-expansion-20261015/evaluation-inputs.json')['inputs']
items=[]
for r in old:
 path=Path(r['image']);contrast=BASE/'coordinate-gap-study-20261015/native-preprocessed'/(r['id']+'@readout-line.contrast.png')
 if not contrast.exists():contrast=BASE/'coordinate-yolo-expansion-20261015/native-preprocessed'/(r['id']+'@readout-line.contrast.png')
 assert contrast.exists();items.append({'id':r['id'],'raw':str(path),'contrast':str(contrast),'imageSize':[892,48],'frameSize':[2560,1440]})
for r in read(ROOT/'new-training-sources.json'):
 fid=r['id'];assert fid not in {i['id'] for i in items}
 items.append({'id':fid,'raw':str(ROOT/'native-training'/(fid+'.raw.png')),'contrast':str(ROOT/'native-training'/(fid+'.contrast.png')),'imageSize':[892,48],'frameSize':[2560,1440]})
for r in read(BASE/'coordinate-sign-layout-20261015/historical-predictions.json')['rows']:
 path=Path(r['image']);items.append({'id':r['id'],'raw':str(path),'contrast':str(path.with_name(path.name.replace('.raw.png','.contrast.png'))),
   'imageSize':[r['shape'][1],r['shape'][0]],'frameSize':[2560,1440] if r['shape'][1]==892 else [1920,1080]})
assert len(items)==416
for item in items:
 for variant in ['raw','contrast']:item[variant+'SHA256']=sha(Path(item[variant]))
