from pathlib import Path
from collections import Counter
import json,hashlib
ROOT=Path(__file__).resolve().parent;BASE=ROOT.parent
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
raw=read(ROOT/'evaluation-reviewed.json');dev={r['id']:r for r in read(BASE/'coordinate-finetune-20261015/paired-v3/development-corpus.json')['frames']}
fit={r['id'] for r in read(ROOT/'training-manifest.json')['rows'] if r['kind']=='annotated-text'}
truth={r['id']:r for r in read(BASE/'coordinate-label-expansion-20261015/expanded-corpus-v5.json')['frames']};truth.update(dev)
hist={r['id']:r for r in read(BASE/'coordinate-sign-layout-20261015/historical-labels.json')}
truth.update({fid:{**r,'state':'present'} for fid,r in hist.items()})
scenes={r['id']:r['sceneGroup'] for r in read(BASE/'coordinate-finetune-20261015/paired-v3/paired-manifest.json')['rows']}
assert not fit&set(dev) and len(fit)==91 and {r['id'] for r in raw['rows']}==fit|set(dev)|set(hist)
def label(f,s):
 if f['state']=='present':return 'miss' if s is None else 'correct' if s['xy']==[f['expected'][k] for k in 'xy'] else 'wrong'
 if f['state']=='absent':return 'trueNegative' if s is None else 'falsePositive'
 return 'unknownNoReturn' if s is None else 'unknownReturned'
counts={};judgments=[];recoveries=[]
for r in raw['rows']:
 fid=r['id'];f=truth[fid]
 groups=['trained-fit-only'] if fid in fit else [hist[fid]['role']] if fid in hist else ['development']
 if fid in dev and fid in scenes:groups.append(scenes[fid])
 if fid in dev and 776<=int(fid[-6:])<=787:groups.append('heldout-stationary-776-787')
 for mode,p in r['pipelines'].items():
  result=label(f,p['selected'])
  for group in groups:
   c=counts.setdefault((mode,group),Counter());c['frames']+=1;c[result]+=1
  j={'id':fid,'mode':mode,'state':f['state'],'trainedFitOnly':fid in fit,'expected':f['expected'],'outcomeXY':result,'selected':p['selected'],'reason':p.get('reason')}
  judgments.append(j)
  if p.get('restoredAxes'):recoveries.append({**j,'restoredAxes':p['restoredAxes'],'confirmations':p['confirmations']})
summary=[{'mode':m,'group':g,**{k:c[k] for k in ['frames','correct','wrong','miss','falsePositive','trueNegative','unknownReturned','unknownNoReturn']}} for (m,g),c in counts.items()]
eligible=['prior-raw-layout','new-raw-layout','new-contrast-layout','new-raw-recovery','prior-raw-new-confirmation']
main={r['mode']:r for r in summary if r['group']=='development'}
qualified=[m for m in eligible if main[m]['correct']>=153 and main[m]['wrong']==main[m]['falsePositive']==0]
assert 'prior-raw-layout' in qualified
chosen=max(qualified,key=lambda m:(main[m]['correct'],-eligible.index(m)))
report={'scope':'Fixed same-session development selection is NOT independent acceptance. Fit91 separate. No old truth changed.',
 'summary':summary,'judgments':judgments,'signRecoveries':recoveries,'selectionRule':'Max correct among>=153 correct,0 known XY wrong,0 absentFP; ties prefer earlier fixed simple pipeline order.',
 'eligibleOrder':eligible,'selectedPipeline':chosen,'independentAcceptanceComplete':False,'productionChanged':False}
out=ROOT/'report-reviewed.json';assert not out.exists();out.write_text(json.dumps(report,ensure_ascii=False,indent=2))
for r in summary:
 if r['group'] in ['development','snow-pale-mixed','heldout-stationary-776-787']:print(r)
print('Selected for independent acceptance',chosen,'recoveries',[(r['mode'],r['id'][-6:],r['outcomeXY']) for r in recoveries])
